(()=>{const light=document.querySelector('.cursor-light'),dot=document.querySelector('.cursor-dot'),ring=document.querySelector('.cursor-ring');let rx=0,ry=0,mx=0,my=0;document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;if(light){light.style.left=mx+'px';light.style.top=my+'px'}if(dot){dot.style.left=mx+'px';dot.style.top=my+'px'}});function tick(){rx+=(mx-rx)*.16;ry+=(my-ry)*.16;if(ring){ring.style.left=rx+'px';ring.style.top=ry+'px'}requestAnimationFrame(tick)}tick();document.querySelectorAll('a,button,input,select,textarea').forEach(el=>{el.addEventListener('mouseenter',()=>document.body.classList.add('cursor-hover'));el.addEventListener('mouseleave',()=>document.body.classList.remove('cursor-hover'))});function spotlight(el,e){const r=el.getBoundingClientRect();el.style.setProperty('--mx',(e.clientX-r.left)+'px');el.style.setProperty('--my',(e.clientY-r.top)+'px')}document.querySelectorAll('.spotlight').forEach(el=>el.addEventListener('mousemove',e=>spotlight(el,e)));document.querySelectorAll('.tilt').forEach(el=>{el.addEventListener('mousemove',e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(900px) rotateX(${(-y*3).toFixed(2)}deg) rotateY(${(x*3).toFixed(2)}deg)`});el.addEventListener('mouseleave',()=>el.style.transform='')});document.querySelectorAll('.magnetic').forEach(el=>{el.addEventListener('mousemove',e=>{const r=el.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);el.style.transform=`translate(${x*.06}px,${y*.06}px)`});el.addEventListener('mouseleave',()=>el.style.transform='')});window.addEventListener('scroll',()=>{const p=document.querySelector('.top-progress');if(!p)return;const d=document.documentElement;p.style.width=((d.scrollTop/(d.scrollHeight-d.clientHeight||1))*100)+'%'},{passive:true})})();
